CREATE OR REPLACE FUNCTION combat_v2_elemental_internal.other_ability_meta(p_actor uuid, p_meta jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE tid uuid;
BEGIN
 IF p_meta->>'source' IS DISTINCT FROM 'clan' THEN RETURN p_meta;END IF;
 tid:=(p_meta->>'id')::uuid;
 IF tid IN ('f1440a58-ee95-53dc-8ed5-a53543d970ce'::uuid,'f0fdbc8e-5cf3-5c9b-af2a-e52869fa8dfc'::uuid,'65719592-7de9-5aa1-8d59-e8da2338d45b'::uuid,'96927a19-9908-59da-9f17-2611e031bd8d'::uuid,'9ac77d79-9894-5388-9753-70538ac5eaa3'::uuid) THEN RETURN combat_v2_taijutsu_internal.ability_meta(p_actor,p_meta);END IF;
 IF combat_v2_elemental_internal.other_profile(p_actor,tid) IS NULL THEN
  IF tid IN ('6d7c0804-1ba9-4e49-8697-1a550f3608b2'::uuid,'b10f8ee7-43ed-4de1-8662-bfcc08ea3a07'::uuid,'d5605069-b381-41ad-8e6a-9c24a314c58f'::uuid,'72cbe1fb-34c8-44c7-a053-0014b4894b3e'::uuid,'29e49eb9-56d7-4d35-afae-af14bf0c8e65'::uuid,'fea014d1-0d71-43dd-bd60-045fbecf3184'::uuid)
   AND p_meta->>'elementali_profile_version'='elementali-genin/1' THEN
   RETURN p_meta-ARRAY['elementali_profile_version','catalog_technique_id','temporary_effect','elementali_effect','effect_description','limits','description'];END IF;
  RETURN p_meta;END IF;
 RETURN p_meta||combat_v2_elemental_internal.other_meta(tid);
END $function$

