 SET search_path TO ''
AS $function$
DECLARE tid uuid;
BEGIN
 IF p_meta->>'source' IS DISTINCT FROM 'clan' THEN RETURN p_meta;END IF;
 tid:=(p_meta->>'id')::uuid;
 IF combat_v2_elemental_internal.suiton_profile(p_actor,tid) IS NULL THEN
  IF tid IN ('1a267759-8d21-4c49-a81f-51b2d4d81db7'::uuid,'4c8e104c-86c7-430b-9700-540170149dd2'::uuid)
   AND p_meta->>'elementali_profile_version'='elementali-genin/1' THEN
   RETURN p_meta-ARRAY['elementali_profile_version','catalog_technique_id','temporary_effect','elementali_effect','effect_description','limits','description'];END IF;
