CREATE OR REPLACE FUNCTION combat_v2_elemental_internal.other_profile(p_actor uuid, p_technique uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.combat_v2_actors%ROWTYPE;p jsonb;public_admitted boolean:=false;
BEGIN
  IF p_technique='31d5d554-44d1-4042-9920-3ddd3bedff7e'::uuid THEN RETURN combat_v2_genjutsu_internal.actor_meta(p_actor);END IF;
 IF p_technique IN ('f1440a58-ee95-53dc-8ed5-a53543d970ce'::uuid,'f0fdbc8e-5cf3-5c9b-af2a-e52869fa8dfc'::uuid,'65719592-7de9-5aa1-8d59-e8da2338d45b'::uuid,'96927a19-9908-59da-9f17-2611e031bd8d'::uuid,'9ac77d79-9894-5388-9753-70538ac5eaa3'::uuid) THEN RETURN combat_v2_taijutsu_internal.profile(p_actor,p_technique);END IF;
 IF NOT EXISTS(SELECT 1 FROM combat_v2_elemental_internal.other_gates WHERE technique_id=p_technique AND enabled) THEN RETURN NULL;END IF;
 SELECT * INTO a FROM public.combat_v2_actors WHERE id=p_actor AND actor_kind IN ('pg','png') AND companion_id IS NULL AND state='attivo';
 IF a.id IS NULL OR NOT combat_effects_private.session_allowed(a.session_id) THEN RETURN NULL;END IF;
 public_admitted:=NOT combat_effects_private.staff_session_allowed(a.session_id) AND EXISTS(SELECT 1 FROM combat_v2_elemental_internal.other_gates WHERE technique_id=p_technique AND enabled AND public_enabled);
 IF NOT combat_effects_private.staff_session_allowed(a.session_id) AND NOT public_admitted THEN RETURN NULL;END IF;
 p:=combat_v2_elemental_internal.technique_profile_v1(p_technique);
 IF jsonb_typeof(a.mechanics_snapshot->'ninjutsu') IS DISTINCT FROM 'number'
  OR (a.mechanics_snapshot->>'ninjutsu')::numeric < (p#>>'{eligibility,ninjutsu_min}')::numeric THEN RETURN NULL;END IF;
 IF a.actor_kind='png' THEN
  IF NOT combat_v2_elemental_internal.other_png_owned(a.id,p_technique) THEN RETURN NULL;END IF;
 ELSIF combat_v2_elemental_internal.other_staff_binding(a.id,p_technique) IS NULL AND
  NOT combat_v2_elemental_internal.eligible_v1(a.character_id,p_technique,false) THEN RETURN NULL;END IF;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(a.mechanics_snapshot->'abilities','[]')) x
  WHERE x->>'source'='clan' AND x->>'id'=p_technique::text) THEN RETURN NULL;END IF;
 RETURN CASE WHEN public_admitted THEN p||jsonb_build_object('runtime_public_admitted',true) ELSE p END;
END $function$

CREATE OR REPLACE FUNCTION combat_v2_elemental_internal.other_consumer_options(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE aid uuid:=(p#>>'{viewer,actor_id}')::uuid;sid uuid:=(p#>>'{context,activity_id}')::uuid;
 a public.combat_v2_actors%ROWTYPE;c combat_consumer_private.activities%ROWTYPE;
 tid uuid;target uuid;profile jsonb;q jsonb;offer jsonb;offers jsonb:=coalesce(p->'offers','[]');push boolean;label text;
BEGIN
 IF aid IS NULL OR sid IS NULL OR p->>'status' IS DISTINCT FROM 'ready' THEN RETURN p;END IF;
 SELECT * INTO a FROM public.combat_v2_actors WHERE id=aid AND session_id=sid AND controller_user=exam_regia_private.current_principal() AND state='attivo';
 SELECT * INTO c FROM combat_consumer_private.activities WHERE session_id=sid AND phase='action' AND turn_actor_id=aid;
 IF a.id IS NULL OR c.session_id IS NULL OR NOT combat_effects_private.session_allowed(sid) THEN RETURN p;END IF;
 SELECT actor_id INTO target FROM combat_consumer_private.members WHERE session_id=sid AND actor_id<>aid;
 FOR tid IN SELECT technique_id FROM combat_v2_elemental_internal.other_gates WHERE enabled ORDER BY technique_id LOOP
  profile:=combat_v2_elemental_internal.technique_profile_v1(tid);
  IF combat_v2_elemental_internal.other_preset_ready(aid,tid) THEN
   offers:=offers||jsonb_build_array(combat_consumer_private.offer_exchange(sid,aid,NULL,(p#>>'{context,scene_version}')::integer,
    'control','Prepara prova: '||(profile->>'name'),jsonb_build_object('other_operation','staff_profile','technique_id',tid)));
  END IF;
  q:=combat_v2_elemental_internal.other_quote(aid,tid);
  IF q IS NULL OR target IS NULL OR EXISTS(SELECT 1 FROM combat_panel_private.multiplication_formations WHERE actor_id=target AND state='active') THEN CONTINUE;END IF;
  IF NOT combat_v2_elemental_internal.other_target_visible(aid,target,CASE WHEN tid='72cbe1fb-34c8-44c7-a053-0014b4894b3e'::uuid THEN combat_v2_elemental_internal.scarica_contact_range(aid,target) ELSE (profile->>'range_m')::numeric END) THEN CONTINUE;END IF;
  FOR push IN SELECT false UNION ALL SELECT true WHERE tid='d5605069-b381-41ad-8e6a-9c24a314c58f'::uuid LOOP
   label:=(profile->>'name')||' · '||(q->>'total')||' chakra'||CASE WHEN tid='d5605069-b381-41ad-8e6a-9c24a314c58f'::uuid THEN
    CASE WHEN push THEN ' · spinge se colpisce' ELSE ' · senza spinta' END ELSE '' END;
   offer:=combat_consumer_private.offer_exchange(sid,aid,target,(p#>>'{context,scene_version}')::integer,'declare',label,
    jsonb_build_object('intent',jsonb_build_object('kind','attacco','ability_source','clan','ability_id',tid,'target_actor',target),
     'other_push_requested',push));
   offers:=offers||jsonb_build_array(offer);
  END LOOP;
 END LOOP;
  RETURN combat_v2_genjutsu_internal.consumer_options(combat_v2_taijutsu_internal.consumer_options(jsonb_set(p,'{offers}',offers)));
END $function$

CREATE OR REPLACE FUNCTION combat_v2_genjutsu_internal.consumer_options(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE aid uuid:=(p#>>'{viewer,actor_id}')::uuid;sid uuid:=(p#>>'{context,activity_id}')::uuid;
 a public.combat_v2_actors%ROWTYPE;c combat_consumer_private.activities%ROWTYPE;t uuid;offers jsonb:=coalesce(p->'offers','[]');q jsonb;ri jsonb;
BEGIN
 IF aid IS NULL OR sid IS NULL OR p->>'status' IS DISTINCT FROM 'ready' THEN RETURN p;END IF;
 SELECT * INTO a FROM public.combat_v2_actors WHERE id=aid AND session_id=sid AND controller_user=exam_regia_private.current_principal() AND state='attivo';
 SELECT * INTO c FROM combat_consumer_private.activities WHERE session_id=sid AND phase='action' AND turn_actor_id=aid;
 IF a.id IS NULL OR c.session_id IS NULL OR NOT combat_v2_genjutsu_internal.runtime_allowed(aid) THEN RETURN p;END IF;
 PERFORM combat_v2_genjutsu_internal.open_turn(sid,aid);
 IF combat_v2_genjutsu_internal.preset_ready(aid) THEN
  offers:=offers||jsonb_build_array(combat_consumer_private.offer_exchange(sid,aid,NULL,(p#>>'{context,scene_version}')::integer,
   'control','Prepara prova: Paralisi illusoria',jsonb_build_object('other_operation','staff_profile','technique_id','31d5d554-44d1-4042-9920-3ddd3bedff7e'::uuid)));
 END IF;
 FOR ri IN SELECT value FROM jsonb_array_elements(combat_v2_genjutsu_internal.release_intents(aid)) LOOP
  offers:=offers||jsonb_build_array(combat_consumer_private.offer_exchange(sid,aid,(ri#>>'{intent,target_actor}')::uuid,(p#>>'{context,scene_version}')::integer,
   'declare',ri->>'label',jsonb_build_object('intent',ri->'intent')));
 END LOOP;
 q:=combat_v2_genjutsu_internal.quote(aid);
 IF q IS NOT NULL THEN
  FOR t IN SELECT x.actor_id FROM combat_consumer_private.members x WHERE x.session_id=sid AND x.actor_id<>aid LOOP
   IF NOT combat_v2_genjutsu_internal.runtime_allowed(t) OR NOT combat_v2_elemental_internal.other_target_visible(aid,t,10)
    OR EXISTS(SELECT 1 FROM combat_panel_private.multiplication_formations WHERE actor_id=t AND state='active') THEN CONTINUE;END IF;
   offers:=offers||jsonb_build_array(combat_consumer_private.offer_exchange(sid,aid,t,(p#>>'{context,scene_version}')::integer,
    'declare','Paralisi illusoria · '||(q->>'total')||' chakra · solo movimento',jsonb_build_object('intent',jsonb_build_object(
     'kind','attacco','ability_source','clan','ability_id','31d5d554-44d1-4042-9920-3ddd3bedff7e'::uuid,'target_actor',t))));
  END LOOP;
 END IF;
 RETURN jsonb_set(p,'{offers}',offers);
END $function$

